import pytest
from project import page_count
@pytest.mark.parametrize("total,size,expected", [(0, 5, 0), (10, 5, 2), (11, 5, 3), (1, 5, 1), (6, 1, 6)])
def test_pages(total, size, expected):
    assert page_count(total, size) == expected
@pytest.mark.parametrize("total,size", [(-1, 5), (1, 0), (1, -2)])
def test_invalid(total, size):
    with pytest.raises(ValueError):
        page_count(total, size)
